//! Design tokens. The colours, sizes and type styles come straight from the design kit's generated
//! `design/tokens/theme.rs` (the single source of truth), so a kit update is a file copy.

#[allow(dead_code)]
#[rustfmt::skip] // generated by the design kit; kept byte-identical so updates are a copy
#[path = "../design/tokens/theme.rs"]
mod kit;

pub use kit::size::*;
#[allow(unused_imports)]
pub use kit::text;
pub use kit::Palette as Tokens;

pub const DARK: Tokens = Tokens::DARK;
pub const LIGHT: Tokens = Tokens::LIGHT;

// Type sizes used across the app (from `text::*`).
pub const TEXT_LABEL: f32 = kit::text::NUM_LABEL.size;
pub const TEXT_BODY: f32 = kit::text::UI_BODY.size;
